# ORF finder both strands
def orfs(s, min_nt=240):
    res=[]
    for f in range(3):
        i=f
        while i < len(s)-2:
            if s[i:i+3]=="ATG":
                j=i+3
                while j < len(s)-2:
                    cod=s[j:j+3]
                    if cod in ("TAA","TAG","TGA"):
                        if j+3-i>=min_nt:
                            res.append((i,j+3,j+3-i))
                        break
                    j+=3
                i=j
            else:
                i+=3
    return res

